function mesaTris(Mm){if(!Mm.P){const b=Uint8Array.from(atob(Mm.q),c=>c.charCodeAt(0)),q=new Int16Array(b.buffer);Mm.P=new Float32Array(q.length);for(let i=0;i<q.length;i++)Mm.P[i]=q[i]/32767*2;
  const P=Mm.P;let inward=0;for(let i=0;i<P.length;i+=9){const ux=P[i+3]-P[i],uy=P[i+4]-P[i+1],uz=P[i+5]-P[i+2],vx=P[i+6]-P[i],vy=P[i+7]-P[i+1],vz=P[i+8]-P[i+2],nx=uy*vz-uz*vy,ny=uz*vx-ux*vz,nz=ux*vy-uy*vx,
      mx=(P[i]+P[i+3]+P[i+6])/3,my=(P[i+1]+P[i+4]+P[i+7])/3,mz=(P[i+2]+P[i+5]+P[i+8])/3;if(nx*mx+ny*(my-Mm.h*0.3)+nz*mz<0)inward++;}
  Mm.flipped=inward>P.length/18?P.length/9:0;if(Mm.flipped)for(let i=0;i<P.length;i+=9)for(let k=0;k<3;k++){const t=P[i+3+k];P[i+3+k]=P[i+6+k];P[i+6+k]=t;}   // a model built inside out (most faces pointing in): turn every face round. (The few inward faces on the others are real hollows and overhangs: left alone.)
}return Mm.P;}
